// Grounded Handbook retrieval for Levlofit AI. Pure and deterministic: no network, no database.
//
// Passages come from handbook-passages.json, generated by data/evidence/extract_claims.py --sync from the Handbook
// builder and the claims evidence register. A passage is one Handbook block, id '<chapter>:bNN' (the prefix of the
// register's claim ids), with the sources the block itself cites and an evidence summary:
//   checked         every claim in the block was checked against a quoted source passage
//   partly_checked  some were
//   unreviewed      none yet; the text may still be right, but nobody has checked it against its source
//   unsourced       reviewed: makes a factual claim but cites no source (general guidance only)
//   editorial       reviewed: Levlofit's own guidance (decision steps, priorities); it claims no evidence
// Retrieval finds Handbook text related to a question. It does not check that the text is correct, and it is not
// a clinical review: passages flagged for clinical review stay flagged in the prompt and in the reply.
import data from './handbook-passages.json' with { type: 'json' };

export type Evidence = 'checked' | 'partly_checked' | 'unreviewed' | 'unsourced' | 'editorial' | 'disputed' | 'no_claims';
export type Passage = {
  id: string;
  chapter: string;
  chapterTitle: string;
  blockType: string;
  text: string;
  sources: string[];
  unknownSources: string[];
  chapterSources: string[];
  evidence: Evidence;
  clinicalReview: boolean;
  claimIds: string[];
};
export type Corpus = { sources: Record<string, string>; passages: Passage[] };
export type Hit = { passage: Passage; score: number };

export const HANDBOOK = data as unknown as Corpus;

const STOP = new Set(
  ('the and for are but not you your yours with what when how why who which this that these those there their they them was were '
    + 'have has had can could should would will shall may might must does did doing done from into onto over under about after before '
    + 'than then just also very much many more most some any all each every per its it\'s our out off too get got make made want need '
    + 'like know tell give good best better way lot lots day days week weeks time times one two') .split(/\s+/),
);

function stem(t: string): string {
  if (t.length > 4 && t.endsWith('ies')) return `${t.slice(0, -3)}y`;
  if (t.length > 5 && t.endsWith('ing')) return t.slice(0, -3);
  if (t.length > 3 && t.endsWith('s') && !t.endsWith('ss')) return t.slice(0, -1);
  return t;
}

/** Lower-case word stems, without stop words or very short words. Numbers are kept. */
export function tokens(text: string): string[] {
  return text
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .filter((t) => t && (/^\d/.test(t) || (t.length >= 3 && !STOP.has(t))))
    .map(stem);
}

type Index = { docs: { tf: Map<string, number>; len: number }[]; df: Map<string, number>; avg: number; usable: Passage[] };
const indexes = new WeakMap<Corpus, Index>();

/** Passages that can ground an answer: not label-only blocks, and not blocks with a claim found unsupported. */
function index(corpus: Corpus): Index {
  const cached = indexes.get(corpus);
  if (cached) return cached;
  const usable = corpus.passages.filter((p) => p.evidence !== 'no_claims' && p.evidence !== 'disputed');
  const df = new Map<string, number>();
  const docs = usable.map((p) => {
    const tf = new Map<string, number>();
    // The chapter title counts twice: it says what the block is about.
    for (const t of [...tokens(p.text), ...tokens(p.chapterTitle), ...tokens(p.chapterTitle)]) tf.set(t, (tf.get(t) ?? 0) + 1);
    for (const t of tf.keys()) df.set(t, (df.get(t) ?? 0) + 1);
    return { tf, len: [...tf.values()].reduce((a, b) => a + b, 0) };
  });
  const built = { docs, df, avg: docs.reduce((a, d) => a + d.len, 0) / Math.max(docs.length, 1), usable };
  indexes.set(corpus, built);
  return built;
}

export const MIN_SCORE = 3.0; // below this a match is a stray common word, not a passage about the question

/**
 * Everyday words a user may type for wording the Handbook uses (word stems, see tokens()). They are matched at half
 * weight and never decide which passages come first, so they widen recall without outranking the question's own
 * words. Kept short and explicit: every target must occur in the Handbook (checked by a test).
 */
export const SYNONYMS: Record<string, string[]> = {
  safe: ['risk', 'adverse', 'harm'],
  safety: ['risk', 'adverse', 'harm'],
  dangerou: ['risk', 'adverse', 'harm'],
  harmful: ['risk', 'adverse'],
  take: ['dose'],
  dosage: ['dose'],
  hurt: ['pain'],
  pregnant: ['pregnancy'],
  depressed: ['depression'],
};
const SYNONYM_WEIGHT = 0.5;

/**
 * The passages most related to [query], best first (BM25 over the passage text and chapter title).
 * Ranking rule: the question's most specific words (the ones found in the fewest passages) anchor it, and passages
 * containing an anchor word come before passages that do not. So "Is creatine safe?" ranks creatine passages above
 * general safety ones, while the minimum score still filters stray matches.
 * [exclude] drops passages naming any of these words, e.g. foods this person must not eat.
 */
export function retrieve(query: string, corpus: Corpus = HANDBOOK, opts: { k?: number; exclude?: string[]; minScore?: number } = {}): Hit[] {
  const { k = 3, exclude = [], minScore = MIN_SCORE } = opts;
  const q = [...new Set(tokens(query))];
  if (!q.length) return [];
  const ix = index(corpus);
  const weights = new Map(q.map((t) => [t, 1]));
  for (const t of q) for (const s of SYNONYMS[t] ?? []) if (!weights.has(s)) weights.set(s, SYNONYM_WEIGHT);
  // A question word the Handbook never uses stands in through its listed synonyms (e.g. "depressed" -> "depression").
  const known = [...new Set(q.flatMap((t) => (ix.df.has(t) ? [t] : (SYNONYMS[t] ?? []).filter((s) => ix.df.has(s)))))];
  const fewest = Math.min(...known.map((t) => ix.df.get(t)!));
  const anchors = new Set(known.filter((t) => ix.df.get(t) === fewest));
  const banned = exclude.filter(Boolean).map((t) => new RegExp(`\\b${t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}`, 'i'));
  const n = ix.docs.length;
  const hits: (Hit & { anchored: boolean })[] = [];
  ix.docs.forEach((d, i) => {
    let score = 0;
    for (const [t, w] of weights) {
      const f = d.tf.get(t);
      if (!f) continue;
      const df = ix.df.get(t)!;
      const idf = Math.log(1 + (n - df + 0.5) / (df + 0.5));
      score += w * idf * ((f * 2.2) / (f + 1.2 * (0.25 + 0.75 * (d.len / ix.avg))));
    }
    const p = ix.usable[i];
    if (score >= minScore && !banned.some((re) => re.test(p.text))) {
      hits.push({ passage: p, score: Math.round(score * 1000) / 1000, anchored: [...anchors].some((t) => d.tf.has(t)) });
    }
  });
  hits.sort((a, b) => Number(b.anchored) - Number(a.anchored) || b.score - a.score || a.passage.id.localeCompare(b.passage.id));
  return hits.slice(0, k).map(({ passage, score }) => ({ passage, score }));
}

/** How a passage's evidence is described to the model and to the user. */
export function evidenceNote(p: Passage): string {
  const base = p.evidence === 'checked'
    ? 'checked against its cited source'
    : p.evidence === 'partly_checked'
      ? 'partly checked against its cited source'
      : p.evidence === 'editorial'
        ? "Levlofit's own guidance, no source claimed"
        : p.evidence === 'unsourced'
          ? 'no source cited; general guidance only'
          : 'not yet checked against its source';
  return p.clinicalReview ? `${base}; needs clinical review` : base;
}

const PASSAGE_CHARS = 700;

/** The prompt block listing retrieved passages, or saying that none matched. Contains Handbook text only. */
export function handbookBlock(hits: Hit[], corpus: Corpus = HANDBOOK): string {
  if (!hits.length) {
    return 'HANDBOOK PASSAGES: none matched this question. Do not cite the Handbook. If the answer needs evidence the Handbook does not give, say the Handbook does not cover it and keep to cautious, general guidance.';
  }
  const lines = hits.map(({ passage: p }) => {
    const src = p.sources.length ? p.sources.map((k) => `${k}: ${corpus.sources[k].slice(0, 120)}`).join(' | ') : 'none cited in this block';
    const text = p.text.length > PASSAGE_CHARS ? `${p.text.slice(0, PASSAGE_CHARS)}…` : p.text;
    return `[H:${p.id}] ${p.chapterTitle}. Evidence: ${evidenceNote(p)}. Sources: ${src}.\n${text}`;
  });
  return `HANDBOOK PASSAGES (Levlofit's own Handbook, matched to this question by keywords; not a clinical review):\n${lines.join('\n\n')}`;
}

/** Rules added to the system prompt for using the passages. */
export const CITATION_RULES = `Handbook passages: when HANDBOOK PASSAGES are listed and you use one, cite it right after the sentence as [H:id], copying an id exactly as listed. Never cite an id that is not listed, and never invent sources, studies or numbers. A passage whose evidence is "not yet checked" is Levlofit's general guidance: do not call it proven, verified or evidence-based. A passage that "needs clinical review" must not be presented as medical advice. If no passage covers the question, say the Handbook does not cover it.`;

export type Grounding = {
  text: string;
  cited: { id: string; title: string; evidence: Evidence; clinicalReview: boolean; sources: string[] }[];
  invalid: string[]; // citation markers removed because they did not match a retrieved passage
};

const MARKER = /\s*\[H:\s*([^\]\n]{0,80})\]/g;

/**
 * Replaces each [H:id] in a reply with a readable Handbook reference when the id was retrieved for this question,
 * and removes any other [H:...] marker. The reference states the passage's evidence status.
 */
export function validateCitations(reply: string, hits: Hit[]): Grounding {
  const byId = new Map(hits.map((h) => [h.passage.id, h.passage]));
  const cited: Grounding['cited'] = [];
  const invalid: string[] = [];
  const seen = new Set<string>();
  const text = reply.replace(MARKER, (_m, raw: string) => {
    const id = raw.trim();
    const p = byId.get(id);
    if (!p) {
      invalid.push(id);
      return '';
    }
    if (seen.has(id)) return '';
    seen.add(id);
    cited.push({ id, title: p.chapterTitle, evidence: p.evidence, clinicalReview: p.clinicalReview, sources: p.sources });
    return ` (Handbook: ${p.chapterTitle}, ${evidenceNote(p)})`;
  });
  return { text: text.replace(/[ \t]+\n/g, '\n').trim(), cited, invalid };
}
